  return selected.indexOf(q?.topic_id) >= 0;
});

if (!pool.length) {
  return { error: 'No questions found for the selected topics.', questions: [] };
}

const shuffled = pool.slice();
for (let i = shuffled.length - 1; i > 0; i--) {
  const j = Math.floor(Math.random() * (i + 1));
  const temp = shuffled[i];
  shuffled[i] = shuffled[j];
  shuffled[j] = temp;
}

const count = Math.min(testSize, shuffled.length);
return { error: '', questions: shuffled.slice(0, count) };

